PROMPTS = [
 ("shoebox-lid / shoebox-closed","Two cutouts of the same worn cardboard shoebox, studio product photo on pure white, 3/4 view matching img/obj/shoebox.png: (a) the box with its lid fully closed, no receipts sticking out; (b) the lid alone, same angle and lighting, transparent background. Lets the lid lift cleanly instead of the current polygon split."),
 ("receipt-thermal-blank","A single long thermal paper receipt, completely faded to blank except a faint header, slightly curled, studio photo on pure white, transparent background, top-down."),
 ("install-photo-supra-turbo","Engine bay of a white 1999 Toyota Supra with a freshly fitted turbo kit, shot from above at a workshop, natural light, no logos (used as an in-app install photo)."),
 ("e30-on-lift","A green BMW E30 raised on a two-post lift in a clean workshop, three-quarter front, natural light, no logos (in-app install photo; replaces the lift + car composite)."),
]
def page():
    out = ['<!doctype html><meta charset="utf-8"><title>Lab C · W44 storyboard</title><style>body{font-family:Inter,system-ui,sans-serif;margin:32px;color:#1D1D1F;max-width:1500px}h1{font-size:30px}h2{margin-top:48px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{border:1px solid #ddd;padding:6px 8px;vertical-align:top;text-align:left}th{background:#F5F5F7}.anim{display:flex;gap:24px;align-items:flex-start}.anim img{width:300px;border-radius:12px;box-shadow:0 0 0 1px #ddd}.sheet{width:100%;margin-top:16px}.g{color:#86868B}</style>',
           '<h1>FuelMyBuild lab lane C · week 44 · C1, G2, P1 v2 · storyboard for approval</h1>',
           '<p class="g">Key frames rendered from the real Remotion scene code (weeks/2026-W44/lab/C/film), lead hooks only, no VO (Wayne records it to vo-script.md). Subtitles show the VO windows. Phase 2 (build polish, sound design, mix, master, renders) waits for Wayne’s approval.</p>']
    for r, d in B.items():
        fr = sorted([f for f in os.listdir(os.path.join(H, r)) if f.endswith(".jpg")], key=lambda x: float(x[:-4]))
        out.append(f'<h2>{html.escape(d["title"])}</h2><div class="anim"><div><img id="a{r}" src="{r}/{fr[0]}"><div class="g" id="t{r}"></div><button onclick="play(\'{r}\')">Play animatic</button></div><div>')
        out.append('<table><tr><th>t (s)</th><th>Voice (Wayne)</th><th>On screen</th><th>Motion</th><th>Sound (cue times, s)</th><th>remocn</th></tr>')
        for b in d["beats"]: out.append("<tr>" + "".join(f"<td>{html.escape(x)}</td>" for x in b) + "</tr>")
        out.append(f'</table><p><b>New remocn pieces vs the previous reel:</b> {html.escape(d["remocn_new"])}</p></div></div>')
        out.append(f'<img class="sheet" src="C-{r}-storyboard-sheet.jpg">')
        out.append(f'<script>window.F=window.F||{{}};F["{r}"]={json.dumps([[float(f[:-4]), f] for f in fr])};</script>')
    out.append('<h2>Score (all three)</h2><p>Original synthesized bed per the sound skill: C1 92 bpm F minor (warm Rhodes + upright-style bass, garage room tone under the body, dead silence 11.5–14.1, back in on the 24.5 downbeat); G2 104 bpm A minor (tight plucks, frame-locked doubled L/R SFX until 5.3 s, ticking pulse 8–10.5, 0.3 s silence before the link); P1 96 bpm D minor (single held note 8.75–11.85, drop back in on the Supra landing). Bed ducked about 7 dB under every VO window; masters at -14 LUFS, true peak ≤ -1 dBTP; plus a music+SFX stem. Every on-screen action in the tables above has its own sound on the same frame.</p>')
    out.append('<h2>Image prompts for new cutouts (optional; current props work)</h2><table><tr><th>id</th><th>prompt</th></tr>' + "".join(f"<tr><td>{a}</td><td>{html.escape(b)}</td></tr>" for a, b in PROMPTS) + '</table><p class="g">All image paths live in film/src/assets.ts, so a new PNG is a one-line swap.</p>')
    out.append('''<script>function play(r){const im=document.getElementById("a"+r),tl=document.getElementById("t"+r),f=F[r];let i=0;const step=()=>{im.src=r+"/"+f[i][1];tl.textContent=f[i][0].toFixed(2)+" s";if(i<f.length-1){const d=(f[i+1][0]-f[i][0])*1000;i++;setTimeout(step,d);}};step();}</script>''')
    open(os.path.join(H, "index.html"), "w").write("\n".join(out))
page()
